Section WithHeap.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (IL : icpt_layout) (LR : HAR.layoutR) (HIk : list (list Z) -> asan_iface)
          (tsp : list (list Z) -> list Z -> credit) (TSRESA : credit).
