Definition flo (h : PQATSG.wsh) : credit := match h with PQATSG.WInl _ _ _ _ => PMSP.cr0 | PQATSG.WDyn _ _ _ _ => (-1, 0) end.
Definition hdr_at (Mx : mem) (o : Z) (h : PQATSG.wsh) : Prop :=
  match h with
  | PQATSG.WInl fb0 _ _ _ => L5.u8_at RSEGS Mx o fb0 /\ 0 <= fb0 < 256 /\ Z.testbit fb0 0 = false
  | PQATSG.WDyn fb0 p _ _ => L5.u8_at RSEGS Mx o fb0 /\ 0 <= fb0 < 256 /\ Z.testbit fb0 0 = true /\ L5.u64_at RSEGS Mx (o + 16) 8 /\ L5.u64_at RSEGS Mx (o + 24) p
                           /\ 4096 <= p /\ p + 64 <= 2 ^ 47
  end.
Lemma hdr_of_ws (Mx : mem) o h : PQATSG.ws_this_atA RSEGS Mx o h -> hdr_at Mx o h.
Proof.
