Definition PREs1 (x : Z * Z * Z * nat * Z * Z) (Rx : bvmap 5 word) (Mx : mem) (FFx : list fframe) (o : Z) : Prop :=
  match x with (o2, fbx, fby, leny, x0, y0) =>
    getr Rx (reg 11) = Z_to_bv 64 o2 /\ PMSPA.aobjA FFx o2 32 /\ o2 mod 8 = 0 /\ PMSPA.accA Mx o2 32 /\ (o + 32 <= o2 \/ o2 + 32 <= o) /\
    PQATSS.binl_at RSEGS Mx o fbx 1%nat x0 0 /\ 1 <= x0 /\ Z.testbit fbx 1 = true /\
    PQATSS.binl_at RSEGS Mx o2 fby leny y0 0 /\ leny = PQATSS.wlen y0 0 /\ Z.testbit fby 1 = false end.
Definition POSTs1 (x : Z * Z * Z * nat * Z * Z) (Rx : bvmap 5 word) (Mx : mem) (o : Z) : Prop :=
  match x with (o2, fbx, fby, leny, x0, y0) =>
    getr Rx (reg 10) = Z_to_bv 64 o /\ exists lo hi, lo + 2 ^ 64 * hi = x0 + y0 /\ PQATSG.ws_this_atA RSEGS Mx o (PQATSG.WInl fbx (PQATSS.wlen lo hi) lo hi) end.
